for(const id of ['manual-dialog','settings-dialog','lab-dialog'])$(id).addEventListener('close',()=>{if(activeModal===id){activeModal=null;if(resumeAfterModal&&!sim.ended)sim.running=true;resumeAfterModal=false;updateUI();}});
$('help').onclick=()=>openDialog('manual-dialog');$('manual-ready').onclick=()=>$('manual-dialog').close();$('settings').onclick=()=>openDialog('settings-dialog');
$('save-settings').onclick=()=>{settings={volume:+$('volume').value,music:+$('music-volume').value,voice:$('voice').checked,reduced:$('reduced').checked,difficulty:$('difficulty').value};audio.setVolume(settings.volume/100);audio.setMusicVolume(settings.music/100);audio.voice=settings.voice;if(audio.ambientGain)audio.ambientGain.gain.value=settings.voice?.16:0;renderer.reduced=settings.reduced;try{localStorage.setItem('blackout-settings',JSON.stringify(settings));}catch{}$('settings-dialog').close();toast('Settings saved. Original v1.43 audio.');};
$('volume').oninput=()=>{$('volume-value').textContent=`${$('volume').value}%`;audio.setVolume(+$('volume').value/100);};$('music-volume').oninput=()=>{$('music-volume-value').textContent=`${$('music-volume').value}%`;audio.setMusicVolume(+$('music-volume').value/100);};
$('sound').onclick=async()=>{const enabled=await audio.toggle();$('sound').innerHTML=`♫ <span>AUDIO ${enabled?'ON':'OFF'}</span>`;$('sound').setAttribute('aria-label',enabled?'Mute sound':'Enable sound');$('sound').setAttribute('aria-pressed',String(enabled));toast(enabled?'Original DEFCON music and sound online.':audio.errors.length?'Audio unavailable. Check media support or network.':'Audio muted.');};
$('begin').onclick=begin;$('pause').onclick=togglePause;document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(+b.dataset.speed));
$('escalate').onclick=()=>{sim.escalate();updateUI();};$('war-tab').onclick=()=>{if(sim.mode==='war')return;configureSimulation();toast('Classic global operation ready.');};$('lab-tab').onclick=()=>{updateLabWarning();openDialog('lab-dialog');};
$('new-game').onclick=()=>{if(sim.running){sim.running=false;toast('Paused. Click NEW OPERATION again to restart.');updateUI();return;}configureSimulation();toast('New operation initialized.');};$('restart').onclick=()=>configureSimulation();$('review-map').onclick=()=>$('result-dialog').close();
$('zoom-in').onclick=()=>renderer.changeZoom(1.3);$('zoom-out').onclick=()=>renderer.changeZoom(1/1.3);$('reset-view').onclick=()=>renderer.reset(sim.mode==='lab');$('layers').onclick=()=>{renderer.coverage=!renderer.coverage;$('layers').setAttribute('aria-pressed',String(renderer.coverage));toast(renderer.coverage?'Allied radar coverage visible.':'Radar coverage hidden.');};
