 const signature=JSON.stringify([u.id,u.hp,u.mode,Math.ceil(u.stateTimer),Math.ceil(u.cooldown),u.fighters,u.bombers,u.ammo,u.stockNukes,Math.floor(u.fuel),u.dead,u.landed,!!u.order,u.returning,sim.phase]);if(signature===inspectorSignature)return;inspectorSignature=signature;
 const t=TYPES[u.type],friendly=u.team===0,base=['carrier','airbase'].includes(u.type),nuclear=['silo','submarine','bomber'].includes(u.type),modes=friendly&&live(u)?modeControls(u):'',fleet=sim.fleets.find(f=>f.id===u.fleetId),members=fleet?sim.units.filter(v=>fleet.members.includes(v.id)&&live(v)):[];
